import math
from nearproof import Measurement, Evidence, RangeDecision, assess, Prover, Verifier, audit

def m(i, d, n=16):
    return Measurement(i, bytes([i])*n, b"r"*32, d/100.0, float(d))

# 5 tight samples at ~10 + one far outlier
samples = [m(1, 10), m(2, 10.2), m(3, 9.8), m(4, 10.1), m(5, 9.9), m(6, 1000)]
d = assess(samples, 11)
print(d, "expected sample_count=6, upper=10.2, accepted True")
assert d == RangeDecision(6, 10.2, True)

# order independence
assert assess(list(reversed(samples)), 11) == d

# limit too tight
assert assess(samples, 10.0).accepted is False

# MAD=0: equal-distance cluster, outlier dropped
s2 = [m(i, 5.0) for i in range(1,6)] + [m(6, 9.0)]
d2 = assess(s2, 5.0)
print(d2, "expected 6, 5.0, True")
assert d2 == RangeDecision(6, 5.0, True)

# too few overall
try: assess(samples[:3], 100)
except ValueError as e: print("few:", e)

# duplicate pair
try: assess([m(1,5), m(1,5), m(2,5), m(3,5), m(4,5)], 100)
except ValueError as e: print("dup:", e)

# negative / nan distance
for bad in (-1.0, math.nan, math.inf):
    try: assess([m(i, bad if i==1 else 5.0) for i in range(1,6)], 100)
    except ValueError as e: print("bad dist", bad, ":", e)

# bad limit/min_samples
for L in (True, -1.0, math.nan, math.inf, "10", 1+2j):
    try: assess([m(i,5) for i in range(1,6)], L)
    except ValueError: pass
    else: raise AssertionError(("limit", L))
for ms in (0, -1, True, 1.0, "5"):
    try: assess([m(i,5) for i in range(1,6)], 100, min_samples=ms)
    except ValueError: pass
    else: raise AssertionError(("min_samples", ms))
print("param checks ok")

# type mixing and invalid types
try: assess([m(1,5), "x", m(2,5), m(3,5), m(4,5)], 100)
except ValueError as e: print("mix:", e)
try: assess([object()]*5, 100)
except ValueError as e: print("invalid:", e)
try: assess(123, 100)
except ValueError as e: print("noniter:", e)

# evidence path via verifier
key = b"k"*16
prov, ver = Prover(key), Verifier(key)
evs = []
for i in range(6):
    ch = ver.new_challenge()
    st = ver.clock()
    evs.append(ver.verify_evidence(ch, prov.respond(ch), st))
blobs = [e.to_bytes() for e in evs]
d3 = assess(blobs, 10.0, key=key)
print(d3)
d4 = assess(evs, 10.0, key=key)
assert d3 == d4
# wrong key / no key
try: assess(evs, 10.0, key=b"z"*16)
except ValueError as e: print("wrong key:", e)
try: assess(evs, 10.0)
except ValueError as e: print("no key:", e)
# tampered bytes
bad_blob = bytearray(blobs[0])
bad_blob[-10] ^= 0xFF
try: assess(evs[:5]+[bytes(bad_blob)], 10.0, key=key)
except ValueError as e: print("tamper:", e)

# mixed Evidence + Measurement
try: assess(evs[:3] + [m(4,1), m(5,1), m(6,1)], 10.0, key=key)
except ValueError as e: print("mix families:", e)

# inlier < min_samples: bimodal with huge MAD? construct: min_samples=3, data [0,0,100,100,100]
dd = assess([m(i, v) for i,v in enumerate([0,0,100,100,100], start=1)], 200, min_samples=3)
print("bimodal:", dd)
# only-two tight with min_samples=3: [0,0,0,1000,1000] median=0 MAD=0 -> inliers=3 ok; make inliers 2:
try:
